<?php $preview=$preview??false; $pageScripts[]='js/booking-extras.js'; $bookingRules=$bookingRules??null; $instantBook=!empty($bookingRules['instant_book']); $holidayRate=$bookingRules['holiday_nightly_rate']??null; ?><section class="detail-page"><div class="container"><div class="detail-heading"><div><p class="breadcrumb-text"><a href="<?= e(url('/')) ?>">Khám phá</a> / <?= e($listing['city']) ?></p><?php if($preview): ?><p class="alert alert-info">Xem trước dành cho Admin · <?= e($listing['moderation_status']) ?> · <a href="<?= e(url('/admin')) ?>">Về quản trị</a></p><?php endif; ?><h1><?= e($listing['title']) ?></h1><p>★ <?= number_format(array_sum(array_column($listing['reviews'],'rating'))/max(1,count($listing['reviews'])),1) ?> · <?= count($listing['reviews']) ?> đánh giá · <?= e($listing['address']) ?></p></div><button class="btn btn-ghost" type="button" data-share>Chia sẻ</button></div><?php $photos = array_slice($listing['photos'], 0, 3); if (!$photos) { $photos = [['image_url' => null, 'alt_text' => 'Chỗ ở chưa có ảnh']]; } ?>
