f="<?= e(url('/reports?listing='.$listing['id'])) ?>">Báo cáo thông tin sai sự thật / lừa đảo</a></p><?php endif; ?><hr><h2>Nội quy và chính sách</h2><p>Nhận phòng từ <?= e(substr($listing['check_in_time'],0,5)) ?> · Trả phòng trước <?= e(substr($listing['check_out_time'],0,5)) ?></p><p><?= $listing['allows_pets']?'Cho phép':'Không cho phép' ?> thú cưng · <?= $listing['allows_smoking']?'Cho phép':'Không cho phép' ?> hút thuốc · <?= $listing['allows_parties']?'Cho phép':'Không cho phép' ?> tiệc</p><p><strong><?= e($listing['cancellation_name']) ?>:</strong> <?= e($listing['cancellation_description']) ?></p><?php if($listing['reviews']): ?><hr><h2>Đánh giá</h2><?php foreach($listing['reviews'] as $review): ?><article class="review"><strong><?= e($review['guest_name']) ?> · <?= str_repeat('★',(int)$review['rating']) ?></strong><?php $badge=['is_verified'=>!empty(($reviewBadges??[])[(int)$review['id']])]; require dirname(__DIR__).'/components/trust-badges.php'; ?><p><?= e($review['comment']) ?></p><?php if(!empty($review['host_reply'])): ?><blockquote class="border-left pl-3"><strong>Phản hồi của Host</strong><p><?= e($review['host_reply']) ?></p></blockquote><?php endif; ?></article><?php endforeach; ?><?php endif; ?><?php require dirname(__DIR__).'/components/calendar.php'; ?></div><div class="col-lg-4"><aside class="booking-box"><div class="booking-price"><strong><?= number_format((float)$listing['nightly_price'],0,',','.') ?>đ</strong> / đêm</div><?php if($instantBook): ?><p class="instant-badge"><span aria-hidden="true">⚡</span> Đặt ngay: xác nhận tức thì, không cần chờ Host duyệt</p><?php endif; ?><?php if($bookingRules): ?><ul class="price-rules"><?php if($bookingRules['weekend_nightly_rate']!==null): ?><li>Đêm thứ Sáu, thứ Bảy: <?= number_format((float)$bookingRules['weekend_nightly_rate'],0,',','.') ?>đ</li><?php endif; ?><?php if($holidayRate!==null): ?><li>Đêm ngày lễ: <?= number_format((float)$holidayRate,0,',','.') ?>đ</li><?php endif; ?><?php if((float)$bookingRules['weekly_discount_pct']>0): ?><li>Giảm <?= e(\App\Services\BookingService::percent((float)$bookingRules['weekly_discount_pct'])) ?> khi ở từ 7 đêm</li><?php endif; ?><?php if((float)$bookingRules['monthly_discount_pct']>0): ?><li>Giảm <?= e(\App\Services\BookingService::percent((float)$bookingRules['monthly_discount_pct'])) ?> khi ở từ 28 đêm</li><?php endif; ?></ul><?php if($holidayRate!==null && !empty($upcomingHolidays)): ?><details class="holiday-list"><summary>Ngày lễ sắp tới</summary><ul><?php foreach($upcomingHolidays as $holiday): ?><li><?= e(date('d/m/Y',strtotime($holiday['holiday_date']))) ?> · <?= e($holiday['name']) ?></li><?php endforeach; ?></ul></details><?php endif; ?><?php endif; ?><form method="post" action="<?= e(url('/listings/'.$listing['id'].'/book')) ?>" data-booking-form data-quote-url="<?= e(url('/api/listings/'.$listing['id'].'/quote')) ?>"><?= csrf_field() ?><div class="form-row"><div class="form-group col-6"><label for="check_in">Nhận phòng</label><input class="form-control" id="check_in" type="date" name="check_in" min="<?= date('Y-m-d') ?>" required></div><div class="form-group col-6"><label for="check_out">Trả phòng</label><input class="form-control" id="check_out" type="date" name="check_out" min="<?= date('Y-m-d',strtotime('+1 day')) ?>" required></div></div><div class="form-group"><label for="guests">Số khách</label><input class="form-control" id="guests" type="number" name="guests" min="1" max="<?= (int)$listing['max_guests'] ?>" value="1" required></div><div class="form-group promo-field"><label for="promo_code">Mã khuyến mãi (không bắt buộc)</label><input class="form-control promo-input" id="promo_code" name="promo_code" maxlength="20" autocomplete="off" spellcheck="false" placeholder="VD: CHAOHE10" data-quote-extra data-promo-input aria-describedby="promo-feedback"><small class="promo-feedback" id="promo-feedback" data-promo-feedback aria-live="polite"></small></div><div class="quote-panel" data-quote><span>Chọn ngày để xem tổng tiền</span></div><?php if($preview): ?><p class="alert alert-info">Chế độ xem trước: không gửi booking.</p><?php elseif(\Core\Auth::check()): ?><button class="btn btn-primary btn-block" type="submit"><?= $instantBook?'Đặt ngay':'Gửi yêu cầu đặt chỗ' ?></button><?php else: ?><a class="btn btn-primary btn-block" href="<?= e(url('/login')) ?>">Đăng nhập để đặt chỗ</a><?php endif; ?><small>Bạn chưa bị tính phí. Tổng tiền được xác nhận lại trên máy chủ.</small><small>Thanh toán trực tiếp khi nhận phòng.</small></form></aside></div></div><?php if(count($listing['photos'])>3): ?><details class="mt-4"><summary>Xem tất cả <?= count($listing['photos']) ?> ảnh</summary><div class="row mt-3"><?php foreach($listing['photos'] as $photo): ?><div class="col-md-4 mb-3"><img class="photo-thumbnail" src="<?= e(image_url($photo['image_url'])) ?>" alt="<?= e($photo['alt_text']) ?>" loading="lazy"></div><?php endforeach; ?></div></details><?php endif; ?></div></section>

